import{_ as a,o as e,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Ajustar eventos de processos migrados do PJe (TJMG)","description":"","frontmatter":{"title":"Ajustar eventos de processos migrados do PJe (TJMG)","id":"eproc-ajustar-eventos-migrados-pje","plataforma":"eproc","tribunal":"TJMG","grupo":"Migração PJe (TJMG)","plano":"free","desde":"1.1.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-ajustar-eventos-migrados-pje.md","filePath":"funcionalidades/eproc-ajustar-eventos-migrados-pje.md"}'),t={name:"funcionalidades/eproc-ajustar-eventos-migrados-pje.md"};function d(i,o,n,c,u,l){return e(),s("div",null,o[0]||(o[0]=[r('<h1 id="ajustar-eventos-de-processos-migrados-do-pje-tjmg" tabindex="-1">Ajustar eventos de processos migrados do PJe (TJMG) <a class="header-anchor" href="#ajustar-eventos-de-processos-migrados-do-pje-tjmg" aria-label="Permalink to &quot;Ajustar eventos de processos migrados do PJe (TJMG)&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Nos processos migrados do PJe para o eproc, os eventos importados &quot;Juntado(a)&quot; trazem a descrição real solta, fora do rótulo, o que dificulta a leitura. Este recurso põe a descrição dentro do rótulo, deixa de fora só o &quot;ID no PJe&quot; e corrige o erro &quot;Publicado Intimação&quot; para &quot;Publicada Intimação&quot;. Também reúne eventos do mesmo ID no PJe que a migração espalhou.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc do TJMG</strong>, página do processo, tabela de eventos, em processos com a etiqueta &quot;Processo Migrado&quot;.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><p>Não é preciso fazer nada. Em processos migrados:</p><ol><li>Os eventos &quot;Juntado(a)&quot; importados mostram a descrição real no rótulo, e o &quot;ID no PJe: ...&quot; fica ao lado, em texto discreto.</li><li>Eventos do mesmo ID no PJe lançados no mesmo instante, mas intercalados com outros, aparecem numa só linha, com os números listados (por exemplo, &quot;29, 31&quot;). Isso depende de <a href="./eproc-agrupar-eventos-relacionados">Agrupar eventos relacionados</a> estar ligado.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Mesclar eventos com o mesmo ID no PJe lançados no mesmo instante, mesmo que intercalados com outros eventos (requer &quot;Agrupar eventos relacionados&quot;)</td><td>ligada</td><td>Junta numa linha os eventos do mesmo ID no PJe.</td></tr><tr><td>Deixar um marcador na posição original dos eventos mesclados fora de sequência</td><td>ligada</td><td>Mostra, no lugar de onde o evento saiu, um marcador que aponta para a linha mesclada. Só aparece com a opção anterior ligada.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O processo é reconhecido como migrado pela etiqueta &quot;Processo Migrado&quot; do topo da página.</li><li>Só eventos com data e hora idênticas são mesclados. Os demais não mudam de lugar.</li><li>Nenhuma informação é apagada: o conteúdo original volta ao desligar o recurso.</li></ul>',12)]))}const h=a(t,[["render",d]]);export{m as __pageData,h as default};
